def is_zero_3x3_center(grid: List[List[int]], r: int, c: int) -> bool:
    """Check if grid[r][c] is the center of a 3x3 block of all zeros"""
    height, width = len(grid), len(grid[0])
    if r < 1 or r >= height-1 or c < 1 or c >= width-1:
        return False
