                return False
    return True

def flood_fill_reach(grid, target_area):
    """
    Flood 0s that can reach the target area (which is outside the box)
    Returns the flood set
    """
    height, width = len(grid), len(grid[0])
    visited = set()
    queue = deque()

    for target_r, target_c in target_area:
        queue.append((target_r, target_c))

    while queue:
        r, c = queue.popleft()
        if (r, c) in visited:
            continue
        if grid[r][c] != 0:
            continue
        visited.add((r, c))

        for dr, dc in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
            nr, nc = r+dr, c+dc
            if 0 <= nr < height and 0 <= nc < width and (nr, nc) not in visited:
                if grid[nr][nc] == 0:
                    queue.append((nr, nc))

    return visited

